CREATE TABLE Produtos (Id NVARCHAR(80) PRIMARY KEY, CompanyId NVARCHAR(40), ProductCode NVARCHAR(80), ProductName NVARCHAR(120), ProductQnt DECIMAL(18,4), ProductUnitPrice DECIMAL(18,4), ProductSalePrice DECIMAL(18,4), TotalPriceOnProduct DECIMAL(18,4));
CREATE TABLE Vendas (Id NVARCHAR(100) PRIMARY KEY, CompanyId NVARCHAR(40), SaleNumber NVARCHAR(30), CustomerName NVARCHAR(120), CustomerCpf NVARCHAR(40), PaymentType NVARCHAR(40), TotalAmount DECIMAL(18,2), OperatorName NVARCHAR(120), SaleDate DATETIMEOFFSET, ClientSaleId NVARCHAR(50), OfflineReference NVARCHAR(60), SyncedAt DATETIMEOFFSET, CaixaSessaoId NVARCHAR(60), Status NVARCHAR(30) DEFAULT 'finalizada', CanceladoEm DATETIMEOFFSET NULL, CanceladoPorOperadorNome NVARCHAR(120) NULL, CanceladoPorSupervisorNome NVARCHAR(120) NULL, CanceladoJustificativa NVARCHAR(120) NULL);
CREATE UNIQUE INDEX IX_Vendas_Number ON Vendas(CompanyId, SaleNumber);
CREATE TABLE VendaItens (Id NVARCHAR(140) PRIMARY KEY, VendaId NVARCHAR(100) REFERENCES Vendas(Id), ProductCode NVARCHAR(80), ProductName NVARCHAR(120), Quantity DECIMAL(18,4), UnitPrice DECIMAL(18,4), Desconto DECIMAL(18,2), ItemTotal DECIMAL(18,2), PromocaoId NVARCHAR(60), CostPrice DECIMAL(18,4));
CREATE TABLE VendaPagamentos (Id NVARCHAR(140) PRIMARY KEY, CompanyId NVARCHAR(40), VendaId NVARCHAR(100) REFERENCES Vendas(Id), PaymentType NVARCHAR(40), Amount DECIMAL(18,2), CashGiven DECIMAL(18,2) NULL, ChangeAmount DECIMAL(18,2) NULL, CreatedAt DATETIMEOFFSET);
CREATE TABLE ProcessedEvents (Id NVARCHAR(80) PRIMARY KEY, CompanyId NVARCHAR(40), EventId NVARCHAR(50), EventType NVARCHAR(50), ClientSaleId NVARCHAR(50), PayloadHash NVARCHAR(64), ProcessedAt DATETIMEOFFSET, ResponsePayload NVARCHAR(MAX), CONSTRAINT UQ_Event UNIQUE(CompanyId,EventId));
CREATE TABLE Clientes (Id NVARCHAR(80) PRIMARY KEY, CompanyId NVARCHAR(40), CustomerName NVARCHAR(120), Document NVARCHAR(40), LimiteCredito DECIMAL(18,2) NOT NULL, SaldoDevedor DECIMAL(18,2) NOT NULL, BirthDate NVARCHAR(30) DEFAULT '', Age NVARCHAR(30) DEFAULT '', Cep NVARCHAR(30) DEFAULT '', City NVARCHAR(100) DEFAULT '', State NVARCHAR(30) DEFAULT '', Address NVARCHAR(120) DEFAULT '', Neighborhood NVARCHAR(100) DEFAULT '', StreetComplement NVARCHAR(100) DEFAULT '', Number NVARCHAR(30) DEFAULT '', ReferencePoint NVARCHAR(100) DEFAULT '', Telephone NVARCHAR(40) DEFAULT '', Cellphone NVARCHAR(40) DEFAULT '', Email NVARCHAR(120) DEFAULT '', IndIeDest TINYINT DEFAULT 9, InscricaoEstadual NVARCHAR(40), CodigoMunicipioIbge NVARCHAR(40));
CREATE TABLE FiadoMovimentos (Id NVARCHAR(80) PRIMARY KEY, CompanyId NVARCHAR(40), ClienteId NVARCHAR(80), Tipo INT, Valor DECIMAL(18,2), SaldoAnterior DECIMAL(18,2), SaldoAtual DECIMAL(18,2), VendaId NVARCHAR(100), FormaPagamento NVARCHAR(40), Observacao NVARCHAR(200), OperadorNome NVARCHAR(120), CriadoEm DATETIMEOFFSET);
CREATE TABLE AuditLog (Id BIGINT IDENTITY PRIMARY KEY, CompanyId NVARCHAR(40), UserId NVARCHAR(80), UserName NVARCHAR(120), EventType NVARCHAR(40), EntityType NVARCHAR(40), EntityId NVARCHAR(80), Description NVARCHAR(1000), Ip NVARCHAR(80), OccurredAt DATETIMEOFFSET DEFAULT SYSDATETIMEOFFSET());
CREATE TABLE Pedidos (Id NVARCHAR(80) PRIMARY KEY, CompanyId NVARCHAR(40), Status INT DEFAULT 0, VendaId NVARCHAR(100), FinalizedAt DATETIMEOFFSET);
CREATE TABLE LoteConfig (CompanyId NVARCHAR(40) PRIMARY KEY, Modo NVARCHAR(40));
